// Fixed tables of glibc's C.UTF-8 character classes and case maps (generated by tools/gen_ctype.cpp).
#pragma once
#include <cstddef>
#include <cstdint>

namespace propan2ol::ctype_tables {

struct CodeRange { uint32_t first, last; };
struct CasePair { uint32_t from, to; };

extern const CodeRange alpha[], space[], upper[], lower[], digit[], punct[], alnum[];
extern const size_t alpha_count, space_count, upper_count, lower_count, digit_count, punct_count, alnum_count;
extern const CasePair to_lower[], to_upper[];
extern const size_t to_lower_count, to_upper_count;

}  // namespace propan2ol::ctype_tables
